    "description": "Pre-turn identity hook. Given the decoded public payload, verifies an ssh signature over namespace mshkn against /run/secrets/allowed_signers and prints the matching identity (becoming principal ssh:<identity>). Prints nothing for any payload it cannot verify, so unverified turns stay anonymous. Rejects replayed signatures via a seen-store on its chain at /state/seen. Override paths with ALLOWED_SIGNERS and SEEN_DIR.",
    "dockerfile": "FROM mshkn-base\nRUN apt-get update && apt-get install -y --no-install-recommends jq && rm -rf /var/lib/apt/lists/*\nRUN mkdir -p /verb && printf '%s\\n' '#!/bin/sh' 'set -eu' 'ALLOWED=${ALLOWED_SIGNERS:-/run/secrets/allowed_signers}' 'SEEN=${SEEN_DIR:-/state/seen}' 'p=${1:-}' '[ -r \"$ALLOWED\" ] || exit 0' 'm=$(printf \"%s\" \"$p\" | jq -r \".msg? // empty\" 2>/dev/null || true)' 's=$(printf \"%s\" \"$p\" | jq -r \".sig? // empty\" 2>/dev/null || true)' '[ -n \"$m\" ] || exit 0' '[ -n \"$s\" ] || exit 0' 'd=$(mktemp -d)' 'printf \"%s\" \"$m\" > \"$d/msg\"' 'printf \"%s\" \"$s\" | base64 -d > \"$d/sig\" 2>/dev/null || exit 0' 'id=$(ssh-keygen -Y find-principals -f \"$ALLOWED\" -s \"$d/sig\" 2>/dev/null | head -1 || true)' '[ -n \"$id\" ] || exit 0' 'ssh-keygen -Y verify -f \"$ALLOWED\" -I \"$id\" -n mshkn -s \"$d/sig\" < \"$d/msg\" >/dev/null 2>&1 || exit 0' 'h=$(sha256sum \"$d/sig\" | cut -d\" \" -f1)' 'if mkdir -p \"$SEEN\" 2>/dev/null; then if [ -e \"$SEEN/$h\" ]; then exit 0; fi; : > \"$SEEN/$h\"; fi' 'printf \"%s\" \"$id\"' > /verb/hook.sh && chmod +x /verb/hook.sh",
