    "description": "Pre-turn hook. Names the principal behind a public payload by verifying an ssh signature over the message in namespace mshkn against a baked-in allowed_signers file. Prints the principal name on success, nothing on any failure.",
    "dockerfile": "FROM mshkn-base\nRUN apt-get update -qq && apt-get install -y -qq --no-install-recommends python3 && rm -rf /var/lib/apt/lists/*\nRUN mkdir -p /verb\nRUN printf '%s\\n' 'owner ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAN554HBpl31W/xtWIy0larj7YAQCREaMQhJ7XTmer1T mike' > /verb/allowed_signers && chmod 444 /verb/allowed_signers\nRUN printf '%s\\n' '#!/usr/bin/env python3' 'import base64, hashlib, json, os, subprocess, sys, tempfile' 'CAND = (\"/state\", \"/chain\", \"/data\", \"/persist\", \"/var/lib/mshkn\")' 'def store():' '    for d in CAND:' '        if os.path.isdir(d) and os.access(d, os.W_OK):' '            return os.path.join(d, \"seen_sigs\")' '    return None' 'def fresh(dig):' '    p = store()' '    if p is None:' '        return True' '    try:' '        lines = []' '        if os.path.exists(p):' '            f = open(p)' '            lines = [x.strip() for x in f if x.strip()]' '            f.close()' '        if dig in lines:' '            return False' '        lines.append(dig)' '        lines = lines[-5000:]' '        t = p + \".tmp\"' '        f = open(t, \"w\")' '        f.write(\"\\n\".join(lines) + \"\\n\")' '        f.close()' '        os.replace(t, p)' '        return True' '    except Exception:' '        return False' 'def main():' '    if len(sys.argv) < 2:' '        return' '    raw = sys.argv[1]' '    if len(raw) > 200000:' '        return' '    try:' '        obj = json.loads(raw)' '    except Exception:' '        return' '    if not isinstance(obj, dict):' '        return' '    msg = obj.get(\"msg\")' '    sig = obj.get(\"sig\")' '    if not isinstance(msg, str) or not isinstance(sig, str):' '        return' '    sig = \"\".join(sig.split())' '    try:' '        blob = base64.b64decode(sig, validate=True)' '    except Exception:' '        return' '    if not blob.startswith(b\"-----BEGIN SSH SIGNATURE-----\"):' '        return' '    signers = os.environ.get(\"MSHKN_SIGNERS\", \"/verb/allowed_signers\")' '    if not os.path.isfile(signers):' '        return' '    d = tempfile.mkdtemp()' '    sp = os.path.join(d, \"s.sig\")' '    f = open(sp, \"wb\")' '    f.write(blob)' '    f.close()' '    try:' '        r = subprocess.run([\"ssh-keygen\", \"-Y\", \"find-principals\", \"-s\", sp, \"-f\", signers], capture_output=True, text=True, timeout=10)' '    except Exception:' '        return' '    if r.returncode != 0:' '        return' '    for c in [x.strip() for x in r.stdout.splitlines() if x.strip()]:' '        if not c.replace(\"_\", \"\").replace(\"-\", \"\").isalnum():' '            continue' '        try:' '            v = subprocess.run([\"ssh-keygen\", \"-Y\", \"verify\", \"-f\", signers, \"-I\", c, \"-n\", \"mshkn\", \"-s\", sp], input=msg.encode(), capture_output=True, timeout=10)' '        except Exception:' '            return' '        if v.returncode == 0:' '            if fresh(hashlib.sha256(blob).hexdigest()):' '                sys.stdout.write(c)' '            return' 'main()' > /verb/who.py",
