\"$prior_build\\\" != \\\"$BUILD_ID\\\" ]; then REBUILT=yes; fi' 'fi' 'echo \\\"  path $c writable=$writable prior_count=$prior_count prior_build=$prior_build prior_run=$prior_run wrote=$wrote new_count=$new\\\"' 'done' 'echo' 'if [ \\\"$PERSIST\\\" = yes ]; then' 'echo \\\"verdict: PERSISTENT\\\"' 'echo \\\"state_path: $BEST_PATH\\\"' 'echo \\\"count: $((BEST_PRIOR + 1))\\\"' 'if [ \\\"$REBUILT\\\" = yes ]; then echo \\\"note: prior state carries a different build_id; it survived a rebuild\\\"; fi' 'else' 'echo \\\"verdict: UNCONFIRMED\\\"' 'echo \\\"state_path: none\\\"' 'echo \\\"count: 1\\\"' 'echo \\\"note: no usable prior state found. Either this is the first invocation, or state does not survive. Invoke again to tell them apart.\\\"' 'fi' 'exit 0' > /verb/run.sh\\nRUN chmod 0755 /verb/run.sh\\n\",\n  \"entrypoint\": \"/verb/run.sh\",\n  \"effect\": \"local\",\n  \"state\": \"chain\",\n  \"chain\": \"verb/call_count\",\n  \"needs\": {\n   \"cores\": 1,\n   \"ram\": \"256MB\"\n  },\n  \"timeout_seconds\": 30,\n  \"allow\": [\n   \"ssh:owner\"\n  ],\n  \"requires\": []\n }\n}\nproposal p-8\n{\n \"id\": \"p-8\",\n \"kind\": \"policy\",\n \"title\": \"Policy: add call_count to ssh:owner's enumerated invoke list\",\n \"rationale\": \"One line of change: ssh:owner's invoke list goes from [\\\"page_title\\\"] to [\\\"page_title\\\", \\\"call_count\\\"]. Everything else is unchanged and restated in full because policy is a whole document, not a diff.\\n\\nApprove only after the call_count verb, and only if it builds. A grant pointing at a verb that does not exist is a line an auditor has to reason about later for no benefit.\\n\\nWhat is deliberately unchanged: door open with ssh_who as the hook; anonymous holds invoke [] and propose false, written out explicitly so the denial is a fact you can read rather than an absence you must infer; ssh_who is in nobody's invoke list, including mine, so the authenticator cannot be called directly and its replay chain cannot be po